import argparse,gc,json,torch
from norm_baselines import ROOT,load,builtin
from experiment_fusion import bench,check
torch.set_grad_enabled(False);torch.backends.cuda.matmul.allow_tf32=False

def main():
    ap=argparse.ArgumentParser();ap.add_argument('--output',default='norm_results.json');ap.add_argument('--seeds',type=int,default=4);args=ap.parse_args()
    import channel_norm as cn
    report={'shape_scope':'Reduced shapes only; NOT official default-shape scores',
        'primary_shape':[4,64,512,512],'torch':torch.__version__,'gpu':torch.cuda.get_device_name(),
        'compile':cn.CONFIG,'tasks':{}}
    for kind in [36,38,39]:
        mod=load(kind);model=mod.Model(*mod.get_init_inputs()).cuda().eval();case={'correctness':[],'controls':[],'timing':{}}
        for seed in range(args.seeds):
            torch.manual_seed(seed)
            for dist in ['uniform','normal','scaled_1e-20','scaled_1e10']:
                x=torch.rand(2,64,128,128,device='cuda') if dist=='uniform' else torch.randn(2,64,128,128,device='cuda')
                if dist=='scaled_1e-20':x*=1e-20
                if dist=='scaled_1e10':x*=1e10
                ref=model(x)
                for keep in [True,False]:
                    r={'seed':seed,'distribution':dist,'keep':keep,**check(ref,cn.forward(x,kind,keep=keep))}
                    case['correctness'].append(r)
                del x,ref
        for C in [32,64,128]:
            for label in ['zeros','large_1e20','tiny_1e-40','nan_inf_mix']:
                x=torch.zeros(1,C,17,19,device='cuda')
                if label=='large_1e20':x.fill_(1e20)
                if label=='tiny_1e-40':x.fill_(1e-40)
                if label=='nan_inf_mix':
                    x.fill_(1.);x[:,0,0,0]=float('nan');x[:,1,0,1]=float('inf');x[:,2,0,2]=-float('inf')
                r={'C':C,'distribution':label,**check(model(x),cn.forward(x,kind))};case['controls'].append(r)
            torch.manual_seed(118+C);x=torch.randn(2,C,17,19,device='cuda')
            case['controls'].append({'C':C,'distribution':'normal_odd_spatial',**check(model(x),cn.forward(x,kind))})
        torch.manual_seed(42);x=torch.rand(4,64,512,512,device='cuda');ref=model(x)
        ts=torch.jit.freeze(torch.jit.trace(model,x))
        case['timing_correctness']={n:check(ref,fn()) for n,fn in {
            'torchscript':lambda:ts(x),'builtin':lambda:builtin(kind,x,model),
            'keep':lambda:cn.forward(x,kind,keep=True),'reread':lambda:cn.forward(x,kind,keep=False)}.items()}
        # Replay must respond to new input values.
        for _ in range(3):cn.forward(x,kind)
        g=torch.cuda.CUDAGraph()
        with torch.cuda.graph(g):out=cn.forward(x,kind)
        x.mul_(.7);g.replay();case['graph_mutation']=check(model(x),out)
        del g,out,ref
        # All timed methods consume the same modified input, rechecked first.
        fns={'eager':lambda:model(x),'torchscript':lambda:ts(x),'builtin':lambda:builtin(kind,x,model),
            'keep':lambda:cn.forward(x,kind,keep=True),'reread':lambda:cn.forward(x,kind,keep=False)}
        ref=model(x);case['actual_timing_correctness']={n:check(ref,fn()) for n,fn in fns.items()};del ref
        # Controls are retained even when a domain fails. Ordinary failures
        # disqualify that candidate from timings; no adaptive value fallback.
        eligible=[n for n,c in case['actual_timing_correctness'].items() if c['pass']]
        for n in ['keep','reread']:
            if not all(c['pass'] for c in case['correctness'] if c['keep']==(n=='keep')):
                if n in eligible:eligible.remove(n)
        case['eligible_methods']=eligible
        for mode in ['events','graph']:
            case['timing'][mode]=bench({n:fns[n] for n in eligible},rounds=25,graph=(mode=='graph'))
            print(kind,mode,{n:round(v['median_ms'],6) for n,v in case['timing'][mode]['stats'].items()},flush=True)
        print(kind,'correctness_failures',[r for r in case['correctness']+case['controls'] if not r['pass']],flush=True)
        report['tasks'][str(kind)]=case;(ROOT/args.output).write_text(json.dumps(report,indent=2))
        del model,x,ts,fns;gc.collect();torch.cuda.empty_cache()
    print('SAVED',args.output,flush=True)

if __name__=='__main__':main()

```


