"""Check compiled specialized built-ins, rather than only compiling reference code."""
import gc,json,torch
import channel_norm as cn
from norm_baselines import ROOT,load,builtin
from experiment_fusion import check,bench
torch.set_grad_enabled(False)
report={'tasks':{},'fused_rms_operator':'not present in local torch.ops.aten'}
for kind in [36,38,39]:
    mod=load(kind);m=mod.Model(*mod.get_init_inputs()).cuda().eval()
    class Builtin(torch.nn.Module):
        def __init__(self):super().__init__();self.model=m
        def forward(self,x):return builtin(kind,x,self.model)
    torch.manual_seed(42);x=torch.rand(4,64,512,512,device='cuda');x*=.7
    ts=torch.jit.freeze(torch.jit.trace(m,x));bt=torch.jit.freeze(torch.jit.trace(Builtin().eval(),x))
    funcs={'eager':lambda:m(x),'torchscript':lambda:ts(x),'builtin':lambda:builtin(kind,x,m),
        'builtin_torchscript':lambda:bt(x),'keep':lambda:cn.forward(x,kind)}
    ref=m(x);checks={n:check(ref,f()) for n,f in funcs.items()};del ref
    eligible={n:f for n,f in funcs.items() if checks[n]['pass']}
    case={'checks':checks,'graph':bench(eligible,rounds=35,graph=True)}
    # Three nondefault eps values are correctness controls, not timing cases.
    if kind==36:
        case['epsilon_controls']=[]
        for eps in [0.,1e-10,1e-3]:
            m.eps=eps;small=torch.randn(2,64,17,19,device='cuda')
